# =========================================================================
# Creep tumors are NOT real buildings: they can't attack, can't produce units,
# and spawn endlessly on creep. Including them causes the army to waste time
# attack-moving to tumors instead of killing actual production/tech structures.
# Also excludes LARVA and EGG (not real structures, just spawned units).
ZERG_JUNK_STRUCTURES = {
    UnitTypeId.LARVA, UnitTypeId.EGG,
    UnitTypeId.CREEPTUMOR, UnitTypeId.CREEPTUMORBURROWED, UnitTypeId.CREEPTUMORQUEEN,
}

# =========================================================================
#  COMPREHENSIVE DEBUG METHODS
#  These methods are called at key points to log detailed per-frame
#  state so future game analysis can identify exactly what went wrong.
# =========================================================================

def _debug_track_stalker_frame(self):
    """
    Per-frame stalker command tracking. Called every frame from on_step.
    Detects when attack commands are overridden before the stalker can fire,
    which was the key bug: stalkers received attack commands that were
    immediately replaced by other commands, resulting in zero damage output.

    Logs:
    - TRACE: Every stalker's current order each frame (MICRO tag)
    - WARN:  Attack reset detected (attack command overridden before firing)
    - INFO:  Periodic summary every 5 seconds
    """
    stalkers = self.units(UnitTypeId.STALKER).ready
    if not stalkers:
        return

    current_frame = getattr(self, 'state', None) and getattr(self.state, 'game_loop', 0) or 0

    for stalker in stalkers:
        tag = stalker.tag
        pos = stalker.position

        # Initialize tracking for this stalker
        if tag not in self._stalker_states:
            self._stalker_states[tag] = {
                "last_ability": None,
                "last_target": None,
                "last_frame": 0,
                "attack_count": 0,
                "move_count": 0,
                "idle_frames": 0,
                "weapon_cd": 0,
                "created_time": self.time,
            }
            self.dbg("MICRO", f"STALKER tag={tag} FIRST SEEN at ({pos.x:.1f},{pos.y:.1f})")

        state = self._stalker_states[tag]
        prev_ability = state["last_ability"]
        prev_frame = state["last_frame"]
        prev_cd = state["weapon_cd"]
        current_cd = stalker.weapon_cooldown

        # Track weapon cooldown transitions
        # If cooldown went from 0 to >0 AND previous command was ATTACK, the attack FIRED
        if prev_cd == 0 and current_cd > 0 and prev_ability in (AbilityId.ATTACK, AbilityId.ATTACK_ATTACK):
            self._stalker_attacks_landed += 1
            self.dbg("MICRO", f"STALKER tag={tag} ATTACK FIRED (weapon_cd 0→{current_cd}) at ({pos.x:.1f},{pos.y:.1f}) total_landed={self._stalker_attacks_landed}")

        # Get current orders
        orders = stalker.orders
        if not orders:
            state["idle_frames"] += 1
            # Log idle stalkers every 50 frames (~2.2s)
            if state["idle_frames"] % 50 == 1:
                self.dbg("MICRO", f"STALKER tag={tag} IDLE for {state['idle_frames']} frames at ({pos.x:.1f},{pos.y:.1f}) weapon_cd={current_cd}")
            state["last_ability"] = None
            state["weapon_cd"] = current_cd
            continue

        current_order = orders[0]
        ability = current_order.ability.id
        target = getattr(current_order, 'target', None)

        # ATTACK RESET DETECTION
        # If the previous command was ATTACK and now it's something different,
        # and the weapon cooldown hasn't started (attack didn't fire yet), that's a reset!
        if (prev_ability in (AbilityId.ATTACK, AbilityId.ATTACK_ATTACK)
            and ability not in (AbilityId.ATTACK, AbilityId.ATTACK_ATTACK)
            and prev_cd == 0  # Weapon hadn't fired yet
            and current_frame - prev_frame < 15):  # Within 15 frames (~0.67s)
            self._stalker_attack_resets += 1
            self.dbg("MICRO", f"STALKER ATTACK RESET! tag={tag} was:ATTACK now:{ability} weapon_cd={current_cd} frames_since_last={current_frame - prev_frame} pos=({pos.x:.1f},{pos.y:.1f}) TOTAL_RESETS={self._stalker_attack_resets}", level="WARN")

        # Track command type
        if ability in (AbilityId.ATTACK, AbilityId.ATTACK_ATTACK):
            if prev_ability not in (AbilityId.ATTACK, AbilityId.ATTACK_ATTACK):
                state["attack_count"] += 1
                target_str = str(target) if target else "none"
                self.dbg("MICRO", f"STALKER tag={tag} ATTACK issued target={target_str} pos=({pos.x:.1f},{pos.y:.1f}) weapon_cd={current_cd} hp={stalker.health:.0f}")
        elif ability in (AbilityId.MOVE, AbilityId.MOVE_MOVE, AbilityId.SMART):
            state["move_count"] += 1
            # Only log moves that override attacks (these are the problematic ones)
            if prev_ability in (AbilityId.ATTACK, AbilityId.ATTACK_ATTACK):
                self.dbg("MICRO", f"STALKER tag={tag} MOVE overriding ATTACK! reason={ability} pos=({pos.x:.1f},{pos.y:.1f}) weapon_cd={current_cd}")

        # Update state
        state["idle_frames"] = 0
        state["last_ability"] = ability
        state["last_target"] = target
        state["last_frame"] = current_frame
        state["weapon_cd"] = current_cd

    # Periodic summary every 5 seconds
    if self.time - self._stalker_last_summary_time >= 5.0:
        self._stalker_last_summary_time = self.time
        total_attacks = sum(s["attack_count"] for s in self._stalker_states.values())
        total_moves = sum(s["move_count"] for s in self._stalker_states.values())
        self.dbg("MICRO", f"STALKER SUMMARY: {len(stalkers)} stalkers | attacks_issued={total_attacks} attacks_landed={self._stalker_attacks_landed} attack_resets={self._stalker_attack_resets} moves={total_moves}")


def _debug_track_observer_idle(self):
    """
    Per-frame observer idle-at-robo detection. Called every frame from on_step.
    Detects when observers sit idle at the robotics facility after spawning,
    which was the bug: observer idled at robo from t=298s to t=322s.

    Logs:
    - WARN: Observer idle at robo for >1.3s (30 frames)
    - ERR:  Observer still idle at robo for >4.4s (100 frames)
    - ERR:  Observer CRITICAL idle at robo for >13s (300 frames)
    - INFO: Observer receives first command after spawning
    """
    observers = self.units(UnitTypeId.OBSERVER)
    if not observers:
        return

    robos = self.structures(UnitTypeId.ROBOTICSFACILITY).ready

    for obs in observers:
        tag = obs.tag
        pos = obs.position

        # Initialize tracking for this observer
        if tag not in self._observer_idle_at_robo:
            self._observer_idle_at_robo[tag] = {
                "frames_idle_at_robo": 0,
                "frames_idle_total": 0,
                "last_warn_time": 0.0,
                "last_command_frame": 0,
                "created_time": self.time,
                "warned_1s": False,
                "warned_4s": False,
                "warned_13s": False,
                "last_state": "SPAWNED",
            }
            self.dbg("MICRO", f"OBSERVER tag={tag} SPAWNED at ({pos.x:.1f},{pos.y:.1f}) t={self.time:.1f}s")

        state = self._observer_idle_at_robo[tag]

        # Check if near a robo facility
        near_robo = False
        closest_robo_dist = 999.0
        for robo in robos:
            dist = obs.distance_to(robo)
            if dist < closest_robo_dist:
                closest_robo_dist = dist
            if dist < 5:
                near_robo = True

        # Check if idle
        is_idle = len(obs.orders) == 0

        if is_idle:
            state["frames_idle_total"] += 1

            if near_robo:
                state["frames_idle_at_robo"] += 1
                state["last_state"] = "AT_ROBO"

                # Escalating warnings
                if state["frames_idle_at_robo"] >= 30 and not state["warned_1s"]:  # ~1.3 seconds
                    state["warned_1s"] = True
                    self.dbg("MICRO", f"OBSERVER IDLE AT ROBO! tag={tag} at ({pos.x:.1f},{pos.y:.1f}) robo_dist={closest_robo_dist:.1f} idle_at_robo_frames={state['frames_idle_at_robo']} t={self.time:.1f}s | BUG - observer should be moving to scout!", level="WARN")

                if state["frames_idle_at_robo"] >= 100 and not state["warned_4s"]:  # ~4.4 seconds
                    state["warned_4s"] = True
                    self.dbg("MICRO", f"OBSERVER STILL IDLE AT ROBO after {state['frames_idle_at_robo']} frames ({self.time - state['created_time']:.1f}s)! tag={tag} Something is preventing observer movement!", level="ERR")

                if state["frames_idle_at_robo"] >= 300 and not state["warned_13s"]:  # ~13 seconds
                    state["warned_13s"] = True
                    self._observer_total_idle_time += 13.0
                    self.dbg("MICRO", f"CRITICAL: Observer idle at robo for {self.time - state['created_time']:.1f}s! This matches the t=298s to t=322s bug. tag={tag} Investigate what's blocking observer movement!", level="ERR")
            else:
                state["last_state"] = "IDLE_NOT_AT_ROBO"
                # Reset robo counter if not near robo anymore
                state["frames_idle_at_robo"] = 0
                state["warned_1s"] = False
                state["warned_4s"] = False
                state["warned_13s"] = False
        else:
            # Observer has orders - reset idle tracking
            order = obs.orders[0]
            ability = order.ability.id
            new_state = f"MOVING({ability})"

            # Log state transitions
            if state["last_state"] != new_state:
                if state["last_state"] in ("AT_ROBO", "IDLE_NOT_AT_ROBO", "SPAWNED"):
                    idle_duration = state["frames_idle_at_robo"] / 22.4  # Approx seconds
                    self.dbg("MICRO", f"OBSERVER tag={tag} state change: {state['last_state']} → {new_state} (was idle at robo for {idle_duration:.1f}s) at ({pos.x:.1f},{pos.y:.1f})")
                    if idle_duration > 1.0:
                        self._observer_total_idle_time += idle_duration

            state["last_state"] = new_state
            state["frames_idle_at_robo"] = 0
            state["frames_idle_total"] = 0
            state["warned_1s"] = False
            state["warned_4s"] = False
            state["warned_13s"] = False
            state["last_command_frame"] = getattr(self, 'state', None) and getattr(self.state, 'game_loop', 0) or 0

    # Clean up dead observers
    dead_tags = [tag for tag in self._observer_idle_at_robo if not observers.find_by_tag(tag)]
    for tag in dead_tags:
        state = self._observer_idle_at_robo[tag]
        self.dbg("MICRO", f"OBSERVER tag={tag} DESTROYED (was in state {state['last_state']}, total_idle_at_robo={self._observer_total_idle_time:.1f}s)")
        del self._observer_idle_at_robo[tag]


def _debug_log_enemy_composition(self):
    """
    Log enemy army composition every 15 seconds. Shows what enemy unit types
    we can see and their counts, so we can track tech switches and army shifts.
    """
    if self.time - self._enemy_comp_last_logged < self._enemy_comp_log_interval:
        return
    self._enemy_comp_last_logged = self.time

    enemy_units = self.enemy_units
    if not enemy_units:
        return

    # Count enemy units by type
    counts = {}
    for unit in enemy_units:
        tid = unit.type_id
        if tid in {UnitTypeId.LARVA, UnitTypeId.EGG}:
            continue
        counts[tid] = counts.get(tid, 0) + 1

    # Build readable string
    parts = []
    for tid, count in sorted(counts.items(), key=lambda x: -x[1]):
        name = str(tid).replace("UnitTypeId.", "")
        parts.append(f"{name}:{count}")

    if parts:
        self.dbg("SUMMARY", f"ENEMY ARMY VISIBLE: {' '.join(parts)}")

    # Also log enemy structures
    enemy_structs = self.enemy_structures
    struct_counts = {}
    for s in enemy_structs:
        tid = s.type_id
        if tid in ZERG_JUNK_STRUCTURES:
            continue
        struct_counts[tid] = struct_counts.get(tid, 0) + 1

    struct_parts = []
    for tid, count in sorted(struct_counts.items(), key=lambda x: -x[1]):
        name = str(tid).replace("UnitTypeId.", "")
        struct_parts.append(f"{name}:{count}")

    if struct_parts:
        self.dbg("SUMMARY", f"ENEMY STRUCTURES VISIBLE: {' '.join(struct_parts)}")

    # Detect composition changes (new unit types appearing)
    new_types = set(counts.keys()) - set(self._last_enemy_unit_counts.keys())
    if new_types and self._last_enemy_unit_counts:
        for nt in new_types:
            name = str(nt).replace("UnitTypeId.", "")
            self.dbg("SCOUT", f"NEW ENEMY UNIT TYPE detected: {name} (count={counts[nt]})")

    self._last_enemy_unit_counts = counts


def _debug_log_upgrade_progress(self):
    """
    Log our upgrade/research progress every 20 seconds so we can track
    when charge, warpgate, armor, blink, etc. complete.
    """
    if self.time - self._upgrade_last_logged < self._upgrade_log_interval:
        return
    self._upgrade_last_logged = self.time

    upgrades_to_track = [
        ("Charge", UpgradeId.CHARGE),
        ("Warpgate", UpgradeId.WARPGATERESEARCH),
        ("+1 Ground Armor", UpgradeId.PROTOSSGROUNDARMORSLEVEL1),
        ("+2 Ground Armor", UpgradeId.PROTOSSGROUNDARMORSLEVEL2),
        ("+1 Ground Weapons", UpgradeId.PROTOSSGROUNDWEAPONSLEVEL1),
        ("+2 Ground Weapons", UpgradeId.PROTOSSGROUNDWEAPONSLEVEL2),
        ("Blink", UpgradeId.BLINKTECH),  # DO NOT use BLINKTECHRESEARCH -- it does not exist!
        ("+1 Air Armor", UpgradeId.PROTOSSAIRARMORSLEVEL1),
        ("+1 Air Weapons", UpgradeId.PROTOSSAIRWEAPONSLEVEL1),
    ]

    parts = []
    for name, uid in upgrades_to_track:
        progress = self.already_pending_upgrade(uid)
        if progress > 0:
            pct = int(progress * 100)
            parts.append(f"{name}={pct}%")

    if parts:
        self.dbg("SUMMARY", f"UPGRADES: {' '.join(parts)}")
    else:
        # Check if any research buildings are active
        twilight = self.structures(UnitTypeId.TWILIGHTCOUNCIL).ready
        forge = self.structures(UnitTypeId.FORGE).ready
        cyber = self.structures(UnitTypeId.CYBERNETICSCORE).ready
        researching = []
        for t in twilight:
            if t.orders:
                researching.append(f"twilight(order={t.orders[0].ability.id})")
        for f in forge:
            if f.orders:
                researching.append(f"forge(order={f.orders[0].ability.id})")
        for c in cyber:
            if c.orders:
                researching.append(f"cyber(order={c.orders[0].ability.id})")
        if researching:
            self.dbg("SUMMARY", f"RESEARCHING (no tracked upgrade): {' '.join(researching)}")


def _debug_log_game_state_summary(self):
    """
    Log comprehensive game state summary every 30 seconds.
    Covers: resources, supply, workers, army, structures, upgrades, enemy intel.
    This is the primary tool for diagnosing game-level issues from logs.
    """
    if self.time - self._summary_last_logged < self._summary_log_interval:
        return
    self._summary_last_logged = self.time

    # Resources & Supply
    probes = self.units(UnitTypeId.PROBE).amount
    nexuses = self.structures(UnitTypeId.NEXUS).amount
    gas = self.structures(UnitTypeId.ASSIMILATOR).ready.amount

    # Army
    stalkers = self.units(UnitTypeId.STALKER).amount
    zealots = self.units(UnitTypeId.ZEALOT).amount
    sentries = self.units(UnitTypeId.SENTRY).amount
    adepts = self.units(UnitTypeId.ADEPT).amount
    observers = self.units(UnitTypeId.OBSERVER).amount
    voidrays = self.units(UnitTypeId.VOIDRAY).amount
    immortals = self.units(UnitTypeId.IMMORTAL).amount
    prism = self.units.of_type({UnitTypeId.WARPPRISM, UnitTypeId.WARPPRISMPHASING}).amount

    # Production
    gw = self.structures(UnitTypeId.GATEWAY).amount
    wg = self.structures(UnitTypeId.WARPGATE).amount
    robo = self.structures(UnitTypeId.ROBOTICSFACILITY).amount
    sg = self.structures(UnitTypeId.STARGATE).amount
    forge = self.structures(UnitTypeId.FORGE).amount
    twilight = self.structures(UnitTypeId.TWILIGHTCOUNCIL).amount
    pylon = self.structures(UnitTypeId.PYLON).amount

    # Key upgrades
    charge_done = self.already_pending_upgrade(UpgradeId.CHARGE) == 1.0
    wg_done = self.already_pending_upgrade(UpgradeId.WARPGATERESEARCH) == 1.0
    armor1 = self.already_pending_upgrade(UpgradeId.PROTOSSGROUNDARMORSLEVEL1)
    blink_done = self.already_pending_upgrade(UpgradeId.BLINKTECH) == 1.0  # DO NOT use BLINKTECHRESEARCH

    # Builder status
    builder_info = "None"
    if self.builder_probe_tag:
        builder = self.units.find_by_tag(self.builder_probe_tag)
        if builder:
            orders_str = str(builder.orders[0].ability.id) if builder.orders else "IDLE"
            builder_info = f"task={self.builder_current_task} pos=({builder.position.x:.0f},{builder.position.y:.0f}) orders={orders_str} locked={self.builder_locked}"
        else:
            builder_info = f"tag={self.builder_probe_tag} NOT_FOUND"

    self.dbg("SUMMARY", f"=== GAME STATE t={self.time:.0f}s ===")
    self.dbg("SUMMARY", f"  RESOURCES: min={self.minerals} gas={self.vespene} supply={self.supply_used}/{self.supply_cap} workers={probes} nexuses={nexuses} gas={gas}")
    self.dbg("SUMMARY", f"  ARMY: stalkers={stalkers} zealots={zealots} sentries={sentries} adepts={adepts} observers={observers} voidrays={voidrays} immortals={immortals} prism={prism}")
    self.dbg("SUMMARY", f"  STRUCTURES: gw={gw} wg={wg} robo={robo} sg={sg} forge={forge} twilight={twilight} pylon={pylon}")
    self.dbg("SUMMARY", f"  UPGRADES: charge={'DONE' if charge_done else 'no'} wg={'DONE' if wg_done else 'no'} armor1={int(armor1*100)}% blink={'DONE' if blink_done else 'no'}")
    self.dbg("SUMMARY", f"  BUILDER: {builder_info}")
    self.dbg("SUMMARY", f"  DEBUG: stalker_resets={self._stalker_attack_resets} stalker_attacks_landed={self._stalker_attacks_landed} obs_total_idle={self._observer_total_idle_time:.1f}s army_wipes={self._army_wipe_count} pylon_redirects={getattr(self, '_pylon_redirect_count', 0)} sticky_pylon={getattr(self, '_sticky_pylon_target', None)}")


class Arpy(AresBot):
    RACE = Race.Protoss
    NAME = "Arpy"

    # Bind unified debug logger
    dbg = _dbg

    # Bind comprehensive debug tracking methods
    _debug_track_stalker_frame = _debug_track_stalker_frame
    _debug_track_observer_idle = _debug_track_observer_idle
    _debug_log_enemy_composition = _debug_log_enemy_composition
    _debug_log_upgrade_progress = _debug_log_upgrade_progress
    _debug_log_game_state_summary = _debug_log_game_state_summary

    # =========================================================================
    #  INITIALIZATION
    # =========================================================================
    def __init__(self, game_step_override=None):
        super().__init__(game_step_override=game_step_override)

        # Debug throttle cache
        self._dbg_throttle_cache = {}

        # Enemy tracking
        self.enemy_worker_tags = set()  # Actual worker units (drones/probes/scvs)
        self.enemy_structure_positions = set()  # Structure positions (x, y, type_id) to prevent duplicates
        self.enemy_main_seen = False
        self.enemy_main_townhall_tag = None
        self.enemy_main_minerals_seen = set()
        self.enemy_main_minerals_complete = False

        # Builder tracking
        self.builder_probe = None
        self.builder_probe_tag = None
        self.builder_locked = False
        self.gas_builder_tag = None  # Separate tracking for gas worker (doesn't overwrite builder_probe_tag)
        self.gas2_builder_tag = None  # Separate tracking for gas 2 worker (hatch-first build order)
        self.gas2_target_tag = None   # Target geyser tag for gas 2 (hatch-first build order)
        self.nexus_first_probe_tag = None
        self._nexus_deferred = False  # True when enemy scout blocks nexus placement
        self._nexus_defer_count = 0   # How many structures built while deferring nexus
        # Unified builder task tracking to prevent command oscillation
        self.builder_current_task = None  # None, "gateway", "pylon", "cyber", etc.
        self.builder_task_target = None   # Position the builder is heading to
        self._builder_released_tags = {}  # {tag: release_time} probes released from builder duty (avoid re-assignment while healing)
        self._builder_in_combat = False   # True when builder probe has enemy within attack range (state machines should not issue move orders)
        self._worker_combat_tags = set()  # Tags of workers currently fighting enemy workers (mining micro should not override)
        self._builder_helper_tag = None   # DEV NOTE #87: Tag of helper probe pulled to fight enemy worker harassing builder (below 90% HP)
        self._builder_swap_immune_until = 0.0  # DEV NOTE #179: Timestamp until which replacement builder is immune to further swaps
        self._builder_stuck_counter = 0   # Increments when builder is at target with build ability but no building appears (stuck detection)
        self._builder_stuck_last_iter = -1  # Last iteration when stuck counter was incremented (prevents double-increment per frame)
        self._builder_position_history = []  # [(game_time, (x, y)), ...] for physical stuck detection (builder trapped between buildings)
        self._failed_build_positions = set()  # Set of (x, y) tuples for positions where building failed (blacklisted)
        self._failed_build_positions_time = {}  # {(x,y): game_time} when the position was blacklisted (for time-based expiry)
        self._battery_build_attempted_stuck = 0  # DEV NOTE #112: Counter for battery build attempts from stuck position
        self._twilight_idle_retry = 0           # DEV NOTE #147: Counter for twilight build retries when builder is idle at target

        # ===== PYLON DEBUG TRACKING =====
        self._pylon_dbg_prev_task = None
        self._pylon_dbg_prev_target = None
        self._pylon_dbg_prev_tag = None
        self._pylon_dbg_prev_locked = None
        self._pylon_dbg_last_log_time = 0.0
        self._pylon_dbg_changes = []  # List of (time, description) changes detected this frame

        # ===== STICKY PYLON POSITION (Dev Note #108) =====
        # Once a pylon position is chosen by manage_flower_production, it's saved
        # here. If the pylon task is cleared and needs reassignment, the same
        # position is reused instead of picking a new one. This prevents the
        # probe from bouncing between different pylon positions when something
        # redirects it away from the target.
        self._sticky_pylon_target = None   # (x, y) tuple or None
        self._sticky_pylon_time = 0.0      # Game time when sticky position was set
        self._pylon_redirect_count = 0     # How many times builder was redirected away from pylon target

        # ===== PYLON BUILD LOCK (Dev Note #110) =====
        # Prevents the "probe standing on pylon position → can_place fails →
        # position invalidated → new position chosen → probe moves → can_place
        # fails again → bounce forever" bug. Same pattern as Dev Note #91
        # (_pvp_main_pylon_ordered) but for flower production pylons.
        self._flower_pylon_ordered = False       # True once build() is issued for a pylon
        self._flower_pylon_ordered_pos = None    # The position build() was issued at
        self._flower_pylon_ordered_time = 0.0    # Game time when build() was issued

        # Worker Age Tracking
        self.worker_creation_queue = [] 
        self.base_creation_queue = []   
        self.held_indices = [] 
        self.prev_held_count = -1     # Track change in builder count
        self.queue_changed = False
        self.last_worker_age_print = 0.0


        # Pylon Builder tracking
        self.pylon_builder = None
        self.pylon_builder_tag = None
        self.pylon_builder_locked = False
        self.flower_reserved = set() # Stores tuples of (x, y) for reserved flower positions


        # Opening build decision
        self.opening_build_chosen = None
        self.opening_probe_scout = None
        self.gas_target_tag = None
        self._pvz_scout_returned_early = False  # True when PvZ scout returns due to low HP or enemy worker chase (Developer Note #114)

        # PvT opening: enemy gas timing detection
        self._pvt_enemy_gas_seen = False  # True once we spot an enemy Refinery (anywhere)
        self._pvt_enemy_gas_time = None   # Game time when enemy Refinery was first spotted
        self._pvt_enemy_refinery_count = 0  # Number of enemy Refineries spotted (2 gas early = heavy tech)
        self._pvt_opening_decided = False # True once PvT opening decision is locked in
        self._pvt_enemy_barracks_seen = False  # True once we spot an enemy Barracks (anywhere)
        self._pvt_enemy_barracks_time = None   # Game time when enemy Barracks was first spotted
        self._pvt_enemy_barracks_pos = None    # Position of first spotted enemy Barracks
        self._pvt_enemy_barracks_ready = False # True once enemy Barracks is complete (triggers scout recall)

        # Emergency supply pylon tracking (DEV NOTE #106)
        self._emergency_pylon_worker_tag = None   # Tag of worker pre-moving to build emergency pylon
        self._emergency_pylon_target = None       # Target position of emergency pylon

        # PvT opening: distance-based detection (within 50 of enemy main)
        self._pvt_enemy_gas_near_main = False       # True once Refinery within 50 of enemymain spotted
        self._pvt_enemy_gas_near_main_time = None   # Game time when Refinery near enemymain first spotted
        self._pvt_enemy_gas2_near_main = False      # True once 2nd Refinery within 50 of enemymain spotted
        self._pvt_enemy_gas2_near_main_time = None  # Game time when 2nd Refinery near enemymain spotted
        self._pvt_enemy_barracks_near_main = False  # True once Barracks within 50 of enemymain spotted
        self._pvt_enemy_barracks_near_main_time = None  # Game time when Barracks near enemymain first spotted
        self._pvt_gas_seen_before_barracks = False  # True if Refinery near main was seen BEFORE Barracks near main (proxy marauder/reaper)
        self._pvt_refinery_positions_near_main = [] # List of Refinery positions within 50 of enemymain
        self._pvt_one_base_4gate = False       # True when pivoting to 1-base 4-gate (gas + no barracks)
        self._pvt_proxy_hidden_tech = False    # True when gas seen + no barracks (proxy hidden tech, immediate detection)
        self._pvt_proxy_rax = False            # True when 15+ workers + no barracks + no gas by 45s (CC first or proxy rax)
        self._pvt_gas2_logged = False          # Track if "2nd gas spotted" log was printed
        self._pvt_enemy_depot_count = 0         # Number of enemy Supply Depots spotted (PvT: 2 depots before rax = weird opener)
        self._pvt_two_depots_before_rax = False  # True when 2 supply depots seen before any barracks
        self._pvt_both_gas_geysers_scouted = False # True once we've had vision of both gas geyser positions near enemy main
        self._pvt_geyser_positions_checked = False  # True once we've cached the enemy main geyser positions
        self._pvt_enemy_main_geysers = []           # Cached list of geyser positions near enemy main
        self._pvt_scout_wrap_triggered = False   # True when 2-depot detection triggers scout wrap around enemy main
        self._scout_shield_skipped = False  # DEV NOTE (scout-shield-skip): One-shot flag (all races) — True once we've skipped the dangerous enemymain mineral-line waypoints (radius 2.8) because the scout's shields dropped below 20%
        self._pvt_scv_peak_near_main = 0         # Peak SCV count seen near enemy main (for forge_first vs reaper_response decision)
        self._pvt_scv_tags_seen = set()          # DEV NOTE #179: Set of SCV tags ever seen near enemy main — permanent count, never removed even if SCV dies
        self._pvt_fleeing_probe_tags = set()    # Probes fleeing/attacking reaper in proxy hidden tech
        self._pvt_gas_pulled_tags = {}           # {worker_tag: assimilator_tag} gas workers pulled off by reaper
        self._retaliation_gas_pulled_tags = {}  # {worker_tag: assimilator_tag} gas workers pulled off by enemy worker retaliation (DEV NOTE #88)
        self._gas_worker_missing_frames = {}   # {worker_tag: frame_count} tracks consecutive frames a gas worker tag is not found (DEV NOTE #104)
        self._pvt_map_sweep_started = False      # True once 5-stalker map sweep begins
        self._pvt_map_sweep_phase = 0            # 0=not started, 1=enemynat, 2=enemymain
        self._pvt_mini_sweep_phase = 0           # DEV NOTE #95: Pre-blink mini sweep: 0=not started, 1=our3rd, 2=our4th, 3=our5th
        self._pvt_mini_sweep_complete = False     # DEV NOTE #95: True once all mini sweep locations have been visited
        self._pvt_shield_battery_started = False  # True once shield battery build is issued at natural for PvT
        self._pvt_supply_pylon_target = None  # DEV NOTE (gw-first-extended): Cached supply pylon position near main pylon
        self._pvt_battery_rally_reissued = False  # DEV NOTE #173: True once gateway rally points re-set to battery+5 after battery completes
        self._pvt_cyber_complete_time = None       # DEV NOTE #161: Time when cyber core first completed (for shield battery fallback timeout)
        self._pvt_battery_rebuild_attempts = 0   # DEV NOTE #115: Track failed battery rebuild attempts for timeout
        self._pvt_battery_first_attempt_time = None  # DEV NOTE #115: Time-based battery rebuild timeout
        self._pvt_battery_retreat_tags = set()   # Stalker tags currently retreating to shield battery
        self._pvt_nat_battery_pos = None        # Cached shield battery position at natural for PvT
        self._pvt_gw_first_state = 0            # PvT gateway_first build state machine
        self._pvt_gw_first_transition_done = False  # True once gateway_first state 6 has transitioned to reaper_response or 4-gate
        self._pvt_cc_first = False              # DEV NOTE #159: True when CC-first detected (no rax, no gas by 60s, 15+ workers)
        self._pvt_cc_first_pivot = False         # DEV NOTE #164: True when CC-first was detected but gas/barracks spotted before nexus → pivot to gateway first
        self._pvt_gw_first_probe_tag = None     # Probe assigned to build gateway + cyber for PvT
        self._pvt_gw_first_gas1_tag = None      # Probe assigned to build gas 1 for PvT
        self._pvt_gw_first_gas2_tag = None      # Probe assigned to build gas 2 for PvT
        self._pvt_gw_first_gas1_geyser = None   # Tag of first geyser for PvT gas
        self._pvt_gw_first_gas2_geyser = None   # Tag of second geyser for PvT gas
        self._pvt_gw_first_log_printed = False  # Track if build order log was printed
        self._pvt_cyber_premove_logged = False  # Track if cyber pre-move log was printed (parallel with gas)

        # PvT reaper response: gateway → nexus → cyber → gas gas → pylon → gw2 → battery → forge → twilight → armor → charge → blink → warpgate
        # Air threat path (starport techlab): armor waits for robo, charge always first, blink after charge
        # Single builder probe chain: same probe builds GW1→Nexus→Cyber→MainPylon→GW2→Battery→Forge→Twilight
        self._pvt_reaper_state = 0             # Reaper response build state machine (0=inactive, 1+=active)
        self._pvt_reaper_probe_tag = None      # Single probe for entire build chain (transferred from gateway_first)
        self._pvt_reaper_builder_released = False  # DEV NOTE #194: True once builder lock is released at state >= 10
